add_filter( 'woocommerce_checkout_fields', 'perfectpixel_readonly_checkout_address_fields', 9999 );

function perfectpixel_readonly_checkout_address_fields( $fields ) {
	if ( ! is_user_logged_in() ) {
		return $fields;
	}

	foreach ( array( 'billing', 'shipping' ) as $group ) {
		if ( empty( $fields[ $group ] ) ) {
			continue;
		}
		foreach ( $fields[ $group ] as $key => $field ) {
			// A <select> ignores "readonly", so render country/state as text inputs.
			if ( in_array( $field['type'] ?? 'text', array( 'country', 'state' ), true ) ) {
				$fields[ $group ][ $key ]['type'] = 'text';
			}
			$fields[ $group ][ $key ]['custom_attributes']['readonly'] = 'readonly';
		}
	}

	return $fields;
}
